    // ─────────── فصل ۱: بنیان‌گذاری ماکوندو ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Founding of Macondo", titlePersian = "بنیان‌گذاری ماکوندو",
        paragraphs = listOf(
            StoryParagraph("Many years later, as he faced the firing squad, Colonel Aureliano Buendía was to remember that distant afternoon when his father took him to discover ice.", "سال‌ها بعد، هنگامی که در برابر جوخه آتش ایستاده بود، سرهنگ اورلیانو بوئندیا می‌بایست آن بعدازظهر دور را به یاد می‌آورد که پدرش او را برای کشف یخ برده بود."),
            StoryParagraph("At that time, Macondo was a village of twenty adobe houses, built on the bank of a river of clear water that ran along a bed of polished stones, which were white and enormous, like prehistoric eggs.", "در آن زمان، ماکوندو دهکده‌ای بود از بیست خانه خشتی، ساخته‌شده در کنار رودخانه‌ای با آب زلال که در بستری از سنگ‌های صیقلی جریان داشت، سنگ‌هایی سفید و عظیم، همچون تخم‌های پیش از تاریخ."),
            StoryParagraph("The world was so recent that many things lacked names, and in order to indicate them it was necessary to point.", "جهان چنان نو بود که بسیاری چیزها نام نداشتند و برای اشاره به آن‌ها لازم بود با انگشت نشانشان داد."),
            StoryParagraph("Every year during the month of March a family of ragged gypsies would set up their tents near the village, and with a great uproar of pipes and kettledrums they would display new inventions.", "هر سال در ماه مارس خانواده‌ای از کولی‌های ژولیده چادرهایشان را نزدیک دهکده برپا می‌کردند و با همهمه‌ای بزرگ از نی‌لبک و طبل‌های کتری‌ای اختراعات نو را به نمایش می‌گذاشتند."),
            StoryParagraph("First they brought the magnet. A heavy gypsy with an untamed beard and sparrow hands, who introduced himself as Melquíades, put on a bold public demonstration of what he himself called the eighth wonder of the learned men of Macedonia.", "نخست آهن‌ربا آوردند. کولی‌ای سنگین‌وزن با ریشی رام‌نشده و دستانی چون گنجشک، که خود را مِلکیادس معرفی کرد، نمایشی جسورانه و علنی از آنچه خودش هشتمین عجایب حکمای مقدونیه می‌نامید به راه انداخت."),
            StoryParagraph("José Arcadio Buendía, whose unbridled imagination always went beyond the genius of nature and even beyond miracles and magic, thought that it would be a good idea to use the magnet to extract gold from the earth.", "خوزه آرکادیو بوئندیا که تخیل بی‌لگامش همیشه از نبوغ طبیعت و حتی از معجزات و جادو فراتر می‌رفت، فکر کرد ایده خوبی است که از آهن‌ربا برای استخراج طلا از زمین استفاده کند."),
            StoryParagraph("He dragged the magnet through the mud and through the rivers, and at the end of several months, he had only managed to bring up a suit of fifteenth-century armor, rusted and full of holes.", "آهن‌ربا را در گل و رودخانه‌ها کشید و در پایان چند ماه، تنها موفق شد زرهی از قرن پانزدهم را بیرون بکشد، زنگ‌زده و پر از سوراخ."),
            StoryParagraph("When Melquíades demonstrated the magnet, José Arcadio Buendía paid him with a mule and a pair of goats, believing that the instrument would help him find gold.", "وقتی مِلکیادس آهن‌ربا را نمایش داد، خوزه آرکادیو بوئندیا با قاطری و جفتی بز پرداختش، باور داشت که این ابزار به او در یافتن طلا کمک می‌کند."),
            StoryParagraph("The gypsies returned a year later with a magnifying glass, which they presented as the latest discovery of the astronomers of Amsterdam.", "کولی‌ها یک سال بعد با ذره‌بین بازگشتند که آن را به‌عنوان آخرین کشف ستاره‌شناسان آمستردام معرفی کردند."),
            StoryParagraph("José Arcadio Buendía, always ready to believe in the wonders of science, traded two mules and a pair of goats for the magnifying glass, and set about using it to set fire to a pile of hay.", "خوزه آرکادیو بوئندیا که همیشه آماده باور به شگفتی‌های علم بود، دو قاطر و جفتی بز را با ذره‌بین معامله کرد و شروع کرد به استفاده از آن برای آتش زدن توده‌ای از علف خشک."),
            StoryParagraph("His experiments with the magnifying glass nearly burned down the house, and his wife Úrsula, furious, forbade him from continuing.", "آزمایش‌هایش با ذره‌بین تقریباً خانه را سوزاند و همسرش اورسولا، خشمگین، ادامه دادن را برایش ممنوع کرد."),
            StoryParagraph("But José Arcadio was not discouraged; he continued to dream of scientific marvels and to plan new experiments.", "اما خوزه آرکادیو ناامید نشد؛ به رؤیا دیدن شگفتی‌های علمی و نقشه کشیدن آزمایش‌های نو ادامه داد."),
            StoryParagraph("The following March, the gypsies returned again, this time with a telescope and a compass.", "مارس بعدی، کولی‌ها دوباره بازگشتند، این بار با تلسکوپی و قطبنمایی."),
            StoryParagraph("Melquíades, who had grown fond of José Arcadio Buendía, gave him the compass as a gift, and with it, the secret knowledge that the earth was round like an orange.", "مِلکیادس که به خوزه آرکادیو بوئندیا علاقه‌مند شده بود، قطبنما را به‌عنوان هدیه به او داد و با آن، دانش پنهان اینکه زمین مثل پرتقال گرد است."),
            StoryParagraph("José Arcadio Buendía, upon hearing this, went mad with excitement; he spent days and nights in the courtyard, observing the stars, trying to prove the roundness of the earth.", "خوزه آرکادیو بوئندیا با شنیدن این، از هیجان دیوانه شد؛ روزها و شب‌ها در حیاط می‌گذراند، ستارگان را مشاهده می‌کرد، تلاش می‌کرد گردی زمین را ثابت کند."),
            StoryParagraph("Úrsula, meanwhile, was raising the family alone, tending to the household, and trying to keep her husband from destroying them all with his mad schemes.", "اورسولا در همین حال، خانواده را تنهایی بزرگ می‌کرد، به خانه رسیدگی می‌کرد و تلاش می‌کرد شوهرش را از نابود کردن همه‌شان با نقشه‌های دیوانه‌وارش باز دارد."),
            StoryParagraph("Their first child, José Arcadio, was born while his father was absorbed in his experiments; the boy grew up wild and strong, more like his father in body than in mind.", "فرزند اولشان، خوزه آرکادیو، هنگامی که پدرش غرق آزمایش‌هایش بود به دنیا آمد؛ پسر وحشی و قوی بزرگ شد، بیشتر در جسم شبیه پدرش تا در ذهن."),
            StoryParagraph("The second child, Aureliano, was born three years later; he was quiet and observant, with a strange ability to predict events before they happened.", "فرزند دوم، اورلیانو، سه سال بعد به دنیا آمد؛ او ساکت و مشاهده‌گر بود، با توانایی عجیبی برای پیش‌بینی رویدادها پیش از وقوعشان."),
            StoryParagraph("When Aureliano was still in his mother's womb, he would weep, and his weeping could be heard by his grandmother, who was not yet born.", "هنگامی که اورلیانو هنوز در شکم مادرش بود، گریه می‌کرد و گریه‌اش توسط مادربزرگش شنیده می‌شد که هنوز به دنیا نیامده بود."),
            StoryParagraph("This was the first sign that the Buendía family was destined for something extraordinary, something that would repeat itself in endless cycles across generations.", "این نخستین نشانه بود که خانواده بوئندیا برای چیزی فوق‌العاده مقدر شده بودند، چیزی که خودش را در چرخه‌های بی‌پایان در طول نسل‌ها تکرار می‌کرد."),
            StoryParagraph("The village of Macondo grew slowly, and with it, the Buendía family grew, adding new members with each passing year.", "دهکده ماکوندو به‌آرامی رشد کرد و با آن، خانواده بوئندیا رشد کرد، هر سال که می‌گذشت اعضای جدیدی اضافه می‌شد."),
            StoryParagraph("By the time Aureliano was old enough to walk, there were already four children in the house, and Úrsula was expecting a fifth.", "تا زمانی که اورلیانو به اندازه کافی بزرگ شد که راه برود، چهار فرزند در خانه بودند و اورسولا منتظر پنجمی بود."),
            StoryParagraph("But the family was not happy; there was a darkness that hung over them, a curse that had been placed on them by the sins of their ancestors.", "اما خانواده خوشحال نبود؛ تاریکی‌ای بر آن‌ها آویزان بود، نفرینی که با گناهان نیاکانشان بر آن‌ها گذاشته شده بود."),
            StoryParagraph("José Arcadio Buendía had killed a man, a man named Prudencio Aguilar, who had insulted his honor; and the ghost of that man haunted him to this day.", "خوزه آرکادیو بوئندیا مردی را کشته بود، مردی به نام پرودنسیو آگیلار که به ناموسش توهین کرده بود؛ و شبح آن مرد تا امروز تسخیرش می‌کرد."),
            StoryParagraph("It was this guilt, this burden, that had driven José Arcadio to leave his old home and to found Macondo in the middle of nowhere, hoping to escape the memory of what he had done.", "این گناه، این بار، بود که خوزه آرکادیو را به ترک خانه قدیمی‌اش و بنیان‌گذاری ماکوندو در میانه هیچ‌کجا کشانده بود، به امید گریز از خاطره آنچه کرده بود."),
            StoryParagraph("But the past cannot be escaped; it follows us wherever we go, and it waits for us at the end of every road.", "اما از گذشته نمی‌توان گریخت؛ هر جا برویم دنبالمان می‌کند و در انتهای هر راه منتظرمان می‌ماند."),
            StoryParagraph("The gypsies came every year, and every year they brought new wonders; and every year, José Arcadio Buendía traded away more of his family's wealth for instruments he did not fully understand.", "کولی‌ها هر سال می‌آمدند و هر سال شگفتی‌های نو می‌آوردند؛ و هر سال، خوزه آرکادیو بوئندیا ثروت بیشتری از خانواده‌اش را با ابزارهایی که کاملاً نمی‌فهمید معامله می‌کرد."),
            StoryParagraph("Úrsula, patient but weary, watched her husband's obsession grow, and she feared what it would do to the family.", "اورسولا، صبور اما خسته، تماشا کرد که وسواس شوهرش رشد می‌کند و می‌ترسید که چه بر سر خانواده می‌آورد."),
            StoryParagraph("One day, Melquíades announced that he had discovered the secret of immortality; he had been to the limits of the world and had seen things that no man had seen before.", "یک روز، مِلکیادس اعلام کرد که راز جاودانگی را کشف کرده؛ او به مرزهای جهان رفته بود و چیزهایی دیده بود که هیچ انسانی قبلاً ندیده بود."),
            StoryParagraph("But the secret, he said, was not one that could be shared; it had to be discovered by each person for themselves.", "اما گفت راز، رازی نبود که بتوان قسمت کرد؛ باید توسط هر شخصی برای خودش کشف شود."),
            StoryParagraph("José Arcadio Buendía was fascinated by this idea, and he spent the next several months trying to discover the secret of immortality.", "خوزه آرکادیو بوئندیا شیفته این ایده شد و چند ماه بعدی را صرف تلاش برای کشف راز جاودانگی کرد."),
            StoryParagraph("But he failed, as he failed at everything, and in his failure, he grew more and more distant from his wife and children.", "اما شکست خورد، همانطور که در همه چیز شکست خورد و در شکستش، بیشتر و بیشتر از همسر و فرزندانش دور شد."),
            StoryParagraph("The years passed, and Macondo remained a small village, isolated from the rest of the world by swamps and jungles.", "سال‌ها گذشت و ماکوندو دهکده کوچکی ماند، منزوی از بقیه جهان توسط باتلاق‌ها و جنگل‌ها."),
            StoryParagraph("But this isolation would not last forever; one day, strangers would come, and with them, the world would intrude on Macondo, and nothing would ever be the same.", "اما این انزوا همیشگی نبود؛ روزی غریبه‌ها می‌آمدند و با آنان، جهان به ماکوندو هجوم می‌آورد و هیچ چیز دیگر هرگز همان نمی‌شد."),
            StoryParagraph("For Macondo, like all things, had its beginning, its middle, and its end; and the end was already written in the manuscripts of Melquíades, though no one yet knew how to read them.", "زیرا ماکوندو، همچون همه چیز، آغاز و میانه و پایانی داشت؛ و پایان از قبل در دست‌نوشته‌های مِلکیادس نوشته شده بود، هرچند هیچ‌کس هنوز نمی‌دانست چگونه بخواندشان."),
            StoryParagraph("And so it was that on a distant afternoon, José Arcadio Buendía took his young son Aureliano to see the ice that the gypsies had brought.", "و اینگونه بود که در بعدازظهری دور، خوزه آرکادیو بوئندیا پسر جوانش اورلیانو را برد تا یخی را که کولی‌ها آورده بودند ببیند."),
            StoryParagraph("The boy would remember that afternoon for the rest of his life; it was the moment when he first understood that the world was full of wonders, and that his father was a man who sought them.", "پسر آن بعدازظهر را تا آخر عمرش به یاد می‌آورد؛ لحظه‌ای بود که نخستین بار فهمید جهان پر از شگفتی است و پدرش مردی بود که دنبالشان می‌گشت."),
            StoryParagraph("This was the first of the many memories that would define Aureliano Buendía, the first of the many threads that would weave the tapestry of his life.", "این نخستین خاطره از خاطرات بسیاری بود که اورلیانو بوئندیا را تعریف می‌کرد، نخستین رشته از رشته‌های بسیاری که قالی زندگی‌اش را می‌بافت."),
            StoryParagraph("And it was the beginning of the story that would be told, one hundred years later, by the last of the Buendía line, as he read the manuscripts that contained the history of his family.", "و آغاز داستانی بود که صد سال بعد توسط آخرین نفر از نسل بوئندیا، هنگام خواندن دست‌نوشته‌هایی که تاریخ خانواده‌اش را در خود داشتند، تعریف می‌شد."),
            StoryParagraph("But that is another story, and it belongs to another time; for now, there is only Macondo, and the Buendía family, and the river of clear water that runs beside their house.", "اما آن داستان دیگری است و به زمانی دیگر تعلق دارد؛ برای اکنون، تنها ماکوندو هست و خانواده بوئندیا و آن رودخانه آب زلال که کنار خانه‌شان جریان دارد."),
            StoryParagraph("And the ice, which the gypsies brought, and which the boy would remember forever, and which would be, in the end, one of the few things that survived the passage of time.", "و یخ، که کولی‌ها آوردند، و پسر برای همیشه به یاد می‌آورد، و در نهایت یکی از اندک چیزهایی می‌شد که از گذر زمان جان سالم برد."),
            StoryParagraph("For ice, unlike memory, does not fade; it only melts, and returns, and melts again, in an endless cycle that mirrors the cycles of the Buendía family.", "زیرا یخ، برخلاف خاطره، محو نمی‌شود؛ تنها ذوب می‌شود و بازمی‌گردد و دوباره ذوب می‌شود، در چرخه‌ای بی‌پایان که چرخه‌های خانواده بوئندیا را بازتاب می‌دهد."),
            StoryParagraph("And so began the story of Macondo, and of the Buendía family, and of one hundred years of solitude.", "و اینگونه داستان ماکوندو و خانواده بوئندیا و صد سال تنهایی آغاز شد.")
        )
    )

    // ─────────── فصل ۲: کولی‌ها و علم ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "The Gypsies and Science", titlePersian = "کولی‌ها و علم",
        paragraphs = listOf(
            StoryParagraph("The gypsies returned the following March, and with them came Melquíades, older now, wearier, but still carrying the same fire in his eyes.", "کولی‌ها مارس بعدی بازگشتند و با آنان مِلکیادس آمد، حالا پیرتر، خسته‌تر، اما هنوز همان آتش را در چشمانش داشت."),
            StoryParagraph("He brought with him a new invention, a device that could capture images of the past, a device that he called the daguerreotype.", "او اختراعی نو با خود آورد، وسیله‌ای که می‌توانست تصاویر گذشته را ثبت کند، وسیله‌ای که آن را داگرئوتیپ می‌نامید."),
            StoryParagraph("José Arcadio Buendía was fascinated; he had always wanted to preserve the memory of things, to hold on to what was slipping away.", "خوزه آرکادیو بوئندیا شیفته شد؛ او همیشه می‌خواست خاطره چیزها را حفظ کند، چیزی که در حال لغزیدن بود را نگه دارد."),
            StoryParagraph("He traded away more of his family's wealth for the daguerreotype, and he set about trying to photograph God, to prove the existence of the divine.", "او ثروت بیشتری از خانواده‌اش را با داگرئوتیپ معامله کرد و شروع کرد به تلاش برای عکس گرفتن از خدا، برای اثبات وجود الوهیت."),
            StoryParagraph("But the photograph showed only a blur, a mist, a fog; and José Arcadio Buendía was forced to admit that God could not be captured by any human instrument.", "اما عکس تنها تاری را نشان داد، مهی، غباری؛ و خوزه آرکادیو بوئندیا مجبور شد بپذیرد که خدا را نمی‌توان با هیچ ابزار انسانی اسیر کرد."),
            StoryParagraph("His wife Úrsula, who had long since given up trying to understand her husband, simply shook her head and continued with her work.", "همسرش اورسولا که مدت‌ها بود تلاش برای فهمیدن شوهرش را رها کرده بود، تنها سرش را تکان داد و به کارش ادامه داد."),
            StoryParagraph("Their children grew, and with them, Macondo grew; new families arrived, new houses were built, and the village slowly became a town.", "فرزندانشان رشد کردند و با آنان، ماکوندو رشد کرد؛ خانواده‌های جدید آمدند، خانه‌های جدید ساخته شدند و دهکده آرام‌آرام به شهر تبدیل شد."),
            StoryParagraph("José Arcadio, the eldest son, had become a man, tall and strong and wild; he spent his days hunting and his nights with women.", "خوزه آرکادیو، پسر ارشد، مردی شده بود، بلندقد و قوی و وحشی؛ روزهایش را به شکار و شب‌هایش را با زنان می‌گذراند."),
            StoryParagraph("Aureliano, the second son, had become a young man, quiet and thoughtful; he spent his days in his father's laboratory, learning the secrets of alchemy.", "اورلیانو، پسر دوم، جوانی شده بود، ساکت و متفکر؛ روزهایش را در آزمایشگاه پدرش می‌گذراند و رازهای کیمیاگری را می‌آموخت."),
            StoryParagraph("Amaranta, the daughter, had become a young woman, beautiful and proud; she had many suitors but she loved none of them.", "آمارانتا، دختر، زنی جوان شده بود، زیبا و مغرور؛ خواستگاران بسیاری داشت اما هیچ‌کدام را دوست نداشت."),
            StoryParagraph("And then, one day, a young woman named Rebeca arrived at the Buendía house, carrying only a small bag of her parents' ashes.", "و سپس، یک روز، زنی جوان به نام ربکا به خانه بوئندیا رسید، تنها کیسه‌ای کوچک از خاکستر والدینش با خود داشت."),
            StoryParagraph("She was an orphan, distant kin of the family, and she had come to live with them; and her arrival would set in motion a chain of events that would change the family forever.", "او یتیمی بود، از خویشاوندان دور خانواده و آمده بود تا با آنان زندگی کند؛ و ورودش زنجیره‌ای از رویدادها را به راه می‌انداخت که خانواده را برای همیشه تغییر می‌داد."),
            StoryParagraph("Rebeca had a strange habit; she ate earth, secretly, when no one was looking; and this habit, mysterious and disturbing, was a sign of the strange fate that awaited her.", "ربکا عادت عجیبی داشت؛ خاک می‌خورد، پنهانی، وقتی هیچ‌کس نگاه نمی‌کرد؛ و این عادت، مرموز و نگران‌کننده، نشانه‌ای از سرنوشت عجیبی بود که در انتظارش بود."),
            StoryParagraph("Úrsula tried to cure her of the habit, using every remedy she knew, but nothing worked; the girl's hunger for earth could not be satisfied.", "اورسولا تلاش کرد او را از این عادت درمان کند، با هر درمانی که می‌شناخت، اما هیچ کار نکرد؛ گرسنگی دختر برای خاک سیر نمی‌شد."),
            StoryParagraph("Eventually, Úrsula gave up, and allowed Rebeca to eat her earth in peace, hoping that the habit would pass with time.", "سرانجام، اورسولا رها کرد و گذاشت ربکا خاکش را در آرامش بخورد، به امید اینکه عادت با گذر زمان از میان برود."),
            StoryParagraph("Meanwhile, in the laboratory, Aureliano was learning the secrets of alchemy; he was trying to turn base metals into gold, following the instructions in Melquíades' manuscripts.", "در همین حال، در آزمایشگاه، اورلیانو رازهای کیمیاگری را می‌آموخت؛ تلاش می‌کرد فلزات پست را به طلا بدل کند، طبق دستورهای دست‌نوشته‌های مِلکیادس."),
            StoryParagraph("He worked for hours, for days, for weeks, without sleep, without food, without rest; and slowly, the metal began to change, taking on the color and the quality of gold.", "ساعت‌ها کار می‌کرد، روزها، هفته‌ها، بدون خواب، بدون غذا، بدون استراحت؛ و آرام‌آرام، فلز شروع کرد به تغییر، رنگ و کیفیت طلا را به خود می‌گرفت."),
            StoryParagraph("But when at last he succeeded, when at last he held the gold in his hands, he felt nothing; the achievement meant nothing to him; he had discovered that gold was no more valuable than any other metal.", "اما وقتی سرانجام موفق شد، وقتی سرانجام طلا را در دستانش گرفت، هیچ حس نکرد؛ دستاورد برایش هیچ معنایی نداشت؛ کشف کرده بود که طلا از هیچ فلز دیگری ارزشمندتر نیست."),
            StoryParagraph("This was the first sign of the solitude that would define Aureliano's life; he was a man who could achieve anything, but who could find meaning in nothing.", "این نخستین نشانه تنهایی‌ای بود که زندگی اورلیانو را تعریف می‌کرد؛ او مردی بود که می‌توانست هر چیزی به دست آورد، اما در هیچ چیز معنایی نمی‌یافت."),
            StoryParagraph("Melquíades, who visited the family often, noticed this quality in Aureliano, and he was troubled by it; he knew that such solitude was a curse, and that it would bring only suffering.", "مِلکیادس که اغلب به دیدن خانواده می‌آمد، این کیفیت را در اورلیانو متوجه شد و ناراحت شد؛ می‌دانست چنین تنهایی نفرینی است و تنها رنج می‌آورد."),
            StoryParagraph("'You are like me,' Melquíades said to Aureliano one day. 'You see things that others do not see, and you understand things that others do not understand. But this knowledge, this vision, is a burden, not a gift.'", "مِلکیادس یک روز به اورلیانو گفت: «تو مثل منی. چیزهایی می‌بینی که دیگران نمی‌بینند و چیزهایی می‌فهمی که دیگران نمی‌فهمند. اما این دانش، این بینش، باری است نه هدیه.»"),
            StoryParagraph("Aureliano did not understand what Melquíades meant, but he would understand it later, when the solitude had consumed him, when he had become a man who could not connect with anyone.", "اورلیانو نفهمید مِلکیادس چه می‌گوید، اما بعدها می‌فهمید، وقتی تنهایی او را خورده بود، وقتی مردی شده بود که نمی‌توانست با کسی ارتباط برقرار کند."),
            StoryParagraph("Melquíades grew older, and sicker, and one day, he announced that he was going to die; he said goodbye to the Buendía family and disappeared into the jungle.", "مِلکیادس پیرتر شد و بیمارتر و یک روز اعلام کرد که می‌خواهد بمیرد؛ با خانواده بوئندیا خداحافظی کرد و در جنگل ناپدید شد."),
            StoryParagraph("But he did not die; or rather, he died and came back; for Melquíades was not bound by the ordinary rules of life and death.", "اما نمرد؛ یا بهتر، مرد و بازگشت؛ زیرا مِلکیادس به قواعد معمول زندگی و مرگ بسته نبود."),
            StoryParagraph("He returned to Macondo years later, still old, still sick, but still alive; and he asked the Buendía family to give him a room where he could live out his final days.", "سال‌ها بعد به ماکوندو بازگشت، هنوز پیر، هنوز بیمار، اما هنوز زنده؛ و از خانواده بوئندیا خواست اتاقی به او بدهند که بتواند روزهای آخرش را در آن بگذراند."),
            StoryParagraph("Úrsula, who had always been fond of Melquíades, gave him a room in the back of the house; and there, in that room, Melquíades would live for many more years, working on his manuscripts.", "اورسولا که همیشه به مِلکیادس علاقه‌مند بود، اتاقی در انتهای خانه به او داد؛ و آنجا، در آن اتاق، مِلکیادس سال‌های بسیاری بیشتر زندگی می‌کرد، مشغول دست‌نوشته‌هایش."),
            StoryParagraph("The manuscripts, he said, contained the entire history of the Buendía family, from its beginning to its end; but they were written in Sanskrit, and no one could read them.", "می‌گفت دست‌نوشته‌ها تمام تاریخ خانواده بوئندیا را در خود داشتند، از آغاز تا پایانش؛ اما به سانسکریت نوشته شده بودند و هیچ‌کس نمی‌توانست بخواندشان."),
            StoryParagraph("Aureliano asked Melquíades to teach him Sanskrit, and Melquíades agreed; and so began the long apprenticeship that would consume the rest of Aureliano's youth.", "اورلیانو از مِلکیادس خواست سانسکریت به او بیاموزد و مِلکیادس موافقت کرد؛ و اینگونه شاگردی درازی آغاز شد که باقی جوانی اورلیانو را می‌خورد."),
            StoryParagraph("Meanwhile, the town of Macondo continued to grow; new families arrived, new businesses opened, and the village slowly transformed into a bustling town.", "در همین حال، شهر ماکوندو به رشد ادامه داد؛ خانواده‌های جدید آمدند، کسب‌وکارهای جدید باز شدند و دهکده آرام‌آرام به شهری پرجنب‌وجوش تبدیل شد."),
            StoryParagraph("But with growth came change, and with change came loss; the simple innocence of Macondo began to fade, replaced by greed and ambition and desire.", "اما با رشد تغییر آمد و با تغییر از دست دادن؛ بی‌گناهی ساده ماکوندو شروع به محو شدن کرد، جایگزین شده با طمع و جاه‌طلبی و میل."),
            StoryParagraph("José Arcadio Buendía, who had always dreamed of a world of wonders, found himself living in a world of commerce and politics, a world he did not understand and did not like.", "خوزه آرکادیو بوئندیا که همیشه در خواب دنیایی از شگفتی‌ها را می‌دید، خود را در دنیایی از تجارت و سیاست می‌یافت، دنیایی که نمی‌فهمید و دوستش نداشت."),
            StoryParagraph("He retreated to his laboratory, spending his days in solitary study, losing touch with the world around him.", "به آزمایشگاهش عقب‌نشینی کرد، روزهایش را در مطالعه خلوت می‌گذراند و ارتباطش را با دنیای اطرافش از دست می‌داد."),
            StoryParagraph("His wife Úrsula, meanwhile, was running the household, raising the children, and trying to hold the family together.", "همسرش اورسولا در همین حال، خانه را می‌گرداند، بچه‌ها را بزرگ می‌کرد و تلاش می‌کرد خانواده را کنار هم نگه دارد."),
            StoryParagraph("She was the backbone of the family, the one who kept things going while everyone else was lost in their own obsessions and dreams.", "او ستون فقرات خانواده بود، کسی که همه چیز را سرپا نگه می‌داشت در حالی که همه در وسواس‌ها و رؤیاهای خودشان گم بودند."),
            StoryParagraph("And then, one day, when Rebeca was a young woman, a stranger arrived in Macondo, a man named Pietro Crespi, an Italian who had come to sell music boxes.", "و سپس، یک روز، وقتی ربکا زن جوانی شده بود، غریبه‌ای به ماکوندو رسید، مردی به نام پیترو کرسپی، ایتالیایی که آمده بود جعبه‌های موسیقی بفروشد."),
            StoryParagraph("Pietro Crespi was handsome and kind and gentle, and both Rebeca and Amaranta fell in love with him; and thus began the rivalry that would tear the family apart.", "پیترو کرسپی خوش‌قیافه و مهربان و لطیف بود و هم ربکا و هم آمارانتا عاشقش شدند؛ و اینگونه رقابتی آغاز شد که خانواده را از هم می‌درید."),
            StoryParagraph("The Buendía family, which had seemed so solid, so stable, was beginning to crack; and the cracks would only widen, and deepen, until the whole structure came crashing down.", "خانواده بوئندیا که اینقدر محکم به نظر می‌رسید، اینقدر پایدار، شروع به ترک خوردن کرد؛ و ترک‌ها تنها پهن‌تر و عمیق‌تر می‌شدند تا وقتی کل ساختار فرو ریخت."),
            StoryParagraph("But that was in the future, and the future was unknown; for now, there was only the present, and the present was Macondo, and Macondo was life.", "اما آن در آینده بود و آینده ناشناخته؛ برای اکنون، تنها حال بود و حال ماکوندو بود و ماکوندو زندگی بود.")
        )
    )

    // ─────────── فصل ۳: جنگ‌های سرهنگ ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "The Colonel's Wars", titlePersian = "جنگ‌های سرهنگ",
        paragraphs = listOf(
            StoryParagraph("Aureliano Buendía went to war when he was still a young man, driven by a passion that he could not explain and would never fully understand.", "اورلیانو بوئندیا به جنگ رفت وقتی هنوز جوان بود، رانده شده با شوری که نمی‌توانست توضیح دهد و هرگز کاملاً نمی‌فهمید."),
            StoryParagraph("The conservative government had rigged the elections, and the liberals had risen up in rebellion; Aureliano, who had always been quiet and thoughtful, felt called to fight.", "دولت محافظه‌کار انتخابات را دستکاری کرده بود و لیبرال‌ها در شورش برخاسته بودند؛ اورلیانو که همیشه ساکت و متفکر بود، حس کرد به جنگیدن فراخوانده شده."),
            StoryParagraph("He left Macondo without saying goodbye to anyone, not even his mother; he simply walked away one day and did not return for many years.", "بدون خداحافظی با کسی، حتی مادرش، ماکوندو را ترک کرد؛ تنها یک روز راه افتاد و سال‌ها بازنگشت."),
            StoryParagraph("Úrsula, when she learned what he had done, wept for three days; she knew that her son had gone to a place where she could not protect him.", "اورسولا وقتی فهمید چه کرده، سه روز گریه کرد؛ می‌دانست پسرش به جایی رفته که نمی‌تواند از او محافظت کند."),
            StoryParagraph("But she also knew that Aureliano was not like other men, that he had a destiny that was his alone, and that she could not hold him back.", "اما می‌دانست اورلیانو مثل دیگر مردان نبود، سرنوشتی داشت که تنها مال خودش بود و نمی‌توانست نگهش دارد."),
            StoryParagraph("Aureliano Buendía rose quickly through the ranks of the liberal army; he was brave, he was intelligent, and he had a gift for strategy that no one could match.", "اورلیانو بوئندیا به‌سرعت در رده‌های ارتش لیبرال بالا رفت؛ شجاع بود، باهوش بود و استعدادی برای استراتژی داشت که هیچ‌کس نمی‌توانست همتایش باشد."),
            StoryParagraph("He led thirty-two armed uprisings against the government; he fought in a hundred battles; he survived a thousand attempts on his life.", "او سی و دو قیام مسلحانه علیه دولت رهبری کرد؛ در صد نبرد جنگید؛ از هزار تلاش برای کشتنش جان سالم برد."),
            StoryParagraph("But he also began to change; the war, which had begun as a noble cause, became a habit, then an addiction, then a curse.", "اما او هم شروع به تغییر کرد؛ جنگ که به‌عنوان آرمانی نجیب آغاز شده بود، عادت شد، بعد اعتیاد، بعد نفرین."),
            StoryParagraph("He could not stop fighting; he did not know how to live without the thrill of battle, the sense of purpose that it gave him, the meaning that it provided.", "نمی‌توانست از جنگیدن دست بکشد؛ نمی‌دانست چگونه بدون هیجان نبرد زندگی کند، بی‌آن حس هدفی که به او می‌داد، آن معنایی که فراهم می‌کرد."),
            StoryParagraph("He had seventeen sons, all named Aureliano, all born to different mothers, all destined to die young and violently.", "او هفده پسر داشت، همه به نام اورلیانو، همه از مادران مختلف، همه مقدر به مردن جوان و خشونت‌آمیز."),
            StoryParagraph("One night, all seventeen were killed by the government; they were hunted down and shot in a single night, and Aureliano learned of it only days later.", "یک شب، هر هفده نفر توسط دولت کشته شدند؛ در یک شب شکار و تیرباران شدند و اورلیانو تنها چند روز بعد فهمید."),
            StoryParagraph("He wept for them, for the first time in years; he wept not for the sons he had never known, but for the part of himself that had been destroyed.", "برایشان گریست، برای نخستین بار در سال‌ها؛ نه برای پسرانی که هرگز نمی‌شناخت گریست، بلکه برای بخشی از خودش که نابود شده بود."),
            StoryParagraph("But he did not stop fighting; he could not stop; the war had become his identity, his reason for being, his only connection to the world.", "اما از جنگیدن دست نکشید؛ نمی‌توانست؛ جنگ هویتش شده بود، دلیل وجودش، تنها ارتباطش با جهان."),
            StoryParagraph("He fought for twenty years, and in those twenty years, he lost everything: his youth, his friends, his family, his soul.", "بیست سال جنگید و در آن بیست سال، همه چیز را از دست داد: جوانی‌اش، دوستانش، خانواده‌اش، روحش."),
            StoryParagraph("He became a legend, but a legend without meaning; he became a hero, but a hero without purpose; he became a man who had achieved everything and understood nothing.", "او به افسانه‌ای تبدیل شد، اما افسانه‌ای بی‌معنا؛ قهرمانی شد، اما قهرمانی بی‌هدف؛ مردی شد که همه چیز به دست آورده و هیچ چیز نفهمیده بود."),
            StoryParagraph("One day, after a long and brutal campaign, he signed a peace treaty; he had grown tired of the war, tired of the killing, tired of the endless cycle of violence.", "یک روز، پس از کارزاری طولانی و بی‌رحم، پیمان صلحی امضا کرد؛ از جنگ خسته شده بود، از کشتار، از چرخه بی‌پایان خشونت."),
            StoryParagraph("He returned to Macondo, an old man now, tired and broken; and there, in the house where he had been born, he retreated to his workshop.", "به ماکوندو بازگشت، حالا پیرمردی، خسته و شکسته؛ و آنجا، در همان خانه‌ای که در آن زاده شده بود، به کارگاهش عقب‌نشینی کرد."),
            StoryParagraph("He spent his days making little gold fishes, intricate and beautiful, which he sold to whoever would buy them.", "روزهایش را صرف ساختن ماهی‌های طلایی کوچک می‌کرد، پیچیده و زیبا، که به هر کس می‌خرید می‌فروخت."),
            StoryParagraph("And when he had made ten fishes, he melted them down and started again; he did this over and over, in an endless cycle that had no purpose and no end.", "و وقتی ده ماهی می‌ساخت، ذوبشان می‌کرد و از نو شروع می‌کرد؛ این کار را بارها و بارها می‌کرد، در چرخه‌ای بی‌پایان که نه هدفی داشت و نه پایانی."),
            StoryParagraph("His mother Úrsula, who was now very old, watched him with sadness; she knew that her son was hiding from something, that the gold fishes were a way of avoiding himself.", "مادرش اورسولا که حالا بسیار پیر بود، با اندوه تماشایش می‌کرد؛ می‌دانست پسرش از چیزی پنهان می‌شود، که ماهی‌های طلایی راهی برای اجتناب از خودش بود."),
            StoryParagraph("But she did not try to stop him; she knew that some things could not be fixed, that some wounds could not be healed, that some men could not be saved.", "اما تلاش نکرد متوقفش کند؛ می‌دانست برخی چیزها را نمی‌شود درست کرد، برخی زخم‌ها را نمی‌شود شفا داد، برخی مردان را نمی‌شود نجات داد."),
            StoryParagraph("And so Aureliano Buendía, the greatest hero of the liberal cause, spent the last years of his life making little gold fishes, alone, in the room where he had learned alchemy.", "و اینگونه اورلیانو بوئندیا، بزرگ‌ترین قهرمان آرمان لیبرال، سال‌های آخر عمرش را صرف ساختن ماهی‌های طلایی کوچک کرد، تنها، در همان اتاقی که کیمیاگری آموخته بود."),
            StoryParagraph("He died one day, quietly, in his sleep; and when they found him, he was still holding a half-finished fish in his hands.", "یک روز به‌آرامی در خواب مرد؛ و وقتی پیدایش کردند، هنوز ماهی نیمه‌تمام را در دستانش داشت."),
            StoryParagraph("They buried him in the courtyard, beside the other members of the family; and Úrsula wept, but she also felt a kind of peace, for her son was finally free.", "او را در حیاط دفن کردند، کنار دیگر اعضای خانواده؛ و اورسولا گریست، اما نوعی آرامش هم حس کرد، زیرا پسرش سرانجام آزاد شده بود."),
            StoryParagraph("The war was over, but its consequences would last for generations; the Buendía family would never recover from what Aureliano had done.", "جنگ تمام شده بود، اما پیامدهایش نسل‌ها ادامه می‌یافت؛ خانواده بوئندیا هرگز از آنچه اورلیانو کرده بود بهبود نمی‌یافت."),
            StoryParagraph("For a curse had been placed on the family, a curse that would manifest itself in endless cycles of solitude and violence and self-destruction.", "زیرا نفرینی بر خانواده گذاشته شده بود، نفرینی که خودش را در چرخه‌های بی‌پایان تنهایی و خشونت و خودتخریبی نشان می‌داد."),
            StoryParagraph("Meanwhile, Macondo continued to grow; the town was becoming a city, and the city was becoming part of the world.", "در همین حال، ماکوندو به رشد ادامه داد؛ شهر داشت شهر می‌شد و شهر داشت بخشی از جهان می‌شد."),
            StoryParagraph("A railway arrived, connecting Macondo to the rest of the country; and with the railway came new people, new ideas, new ways of life.", "راه‌آهنی رسید، ماکوندو را به بقیه کشور وصل کرد؛ و با راه‌آهن مردم جدید آمدند، ایده‌های جدید، شیوه‌های نو زندگی."),
            StoryParagraph("The banana company arrived, bringing with it jobs and money and progress; and with the company came corruption and greed and violence.", "شرکت موز رسید و با خود شغل و پول و پیشرفت آورد؛ و با شرکت فساد و طمع و خشونت آمدند."),
            StoryParagraph("The people of Macondo, who had once been simple and innocent, learned to be cunning and selfish and cruel.", "مردم ماکوندو که زمانی ساده و بی‌گناه بودند، یاد گرفتند حیله‌گر و خودخواه و بی‌رحم باشند."),
            StoryParagraph("The golden age of Macondo was over; the age of darkness had begun.", "عصر طلایی ماکوندو تمام شده بود؛ عصر تاریکی آغاز شده بود."),
            StoryParagraph("But that is the story of another chapter, and it belongs to another generation; for now, there is only Macondo, and the Buendía family, and the slow, inevitable approach of the end.", "اما این داستان فصل دیگری است و به نسل دیگری تعلق دارد؛ برای اکنون، تنها ماکوندو هست و خانواده بوئندیا و نزدیک شدن آرام و اجتناب‌ناپذیر پایان.")
        )
    )

    // ─────────── فصل ۴: کشتار موز ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "The Banana Massacre", titlePersian = "کشتار موز",
        paragraphs = listOf(
            StoryParagraph("The banana company had brought prosperity to Macondo, but it had also brought exploitation; the workers labored long hours for little pay, and they had no rights, no protection, no voice.", "شرکت موز رفاه به ماکوندو آورده بود، اما استثمار هم آورده بود؛ کارگران ساعت‌های طولانی برای دستمزد اندک کار می‌کردند و هیچ حقوقی نداشتند، هیچ حمایتی، هیچ صدایی."),
            StoryParagraph("The workers lived in squalid conditions, in barracks with no windows and no ventilation; they slept on the floor, ate bad food, and died young.", "کارگران در شرایط رقت‌انگیز زندگی می‌کردند، در سربازخانه‌هایی بدون پنجره و بدون تهویه؛ روی زمین می‌خوابیدند، غذای بد می‌خوردند و جوان می‌مردند."),
            StoryParagraph("The company did not care; the company cared only about profit; the company cared only about the bananas that were being shipped to the United States.", "شرکت اهمیتی نمی‌داد؛ شرکت تنها به سود اهمیت می‌داد؛ شرکت تنها به موزهایی که به ایالات متحده فرستاده می‌شدند اهمیت می‌داد."),
            StoryParagraph("And so the workers decided to strike; they wanted better pay, better conditions, better treatment; they wanted to be treated as human beings.", "و بنابراین کارگران تصمیم گرفتند اعتصاب کنند؛ دستمزد بهتر می‌خواستند، شرایط بهتر، رفتار بهتر؛ می‌خواستند مثل انسان با آن‌ها رفتار شود."),
            StoryParagraph("They formed a union, they elected leaders, they organized marches; and the company responded with threats, with beatings, with arrests.", "اتحادیه تشکیل دادند، رهبر انتخاب کردند، راهپیمایی سازمان دادند؛ و شرکت با تهدید پاسخ داد، با کتک، با بازداشت."),
            StoryParagraph("But the workers did not give up; they continued to strike, continued to march, continued to demand their rights.", "اما کارگران تسلیم نشدند؛ به اعتصاب ادامه دادند، به راهپیمایی، به مطالبه حقوقشان."),
            StoryParagraph("And then, one day, the army was sent in; the government had decided to break the strike, no matter the cost.", "و سپس، یک روز، ارتش فرستاده شد؛ دولت تصمیم گرفته بود اعتصاب را بشکند، هر چه هزینه داشته باشد."),
            StoryParagraph("Three thousand workers gathered in the town square, along with their wives and children; they were there to hear the governor speak, to hear what he had to say about their demands.", "سه هزار کارگر در میدان شهر جمع شدند، همراه با همسران و فرزندانشان؛ آنجا بودند تا فرماندار صحبت کند، تا بشنوند درباره مطالباتشان چه می‌گوید."),
            StoryParagraph("But the governor did not come to listen; he came to give an ultimatum: disperse, or face the consequences.", "اما فرماندار نیامده بود گوش کند؛ آمده بود اولتیماتومی بدهد: پراکنده شوید، وگرنه عواقبش را می‌بینید."),
            StoryParagraph("The workers did not disperse; they stood their ground, they refused to leave; and the army was given the order to fire.", "کارگران پراکنده نشدند؛ پایشان ایستادند، از رفتن امتناع کردند؛ و به ارتش دستور آتش داده شد."),
            StoryParagraph("Machine guns opened up from the rooftops, from the windows, from every corner of the square; and the people fell, hundreds, thousands, their bodies piling up in the streets.", "مسلسل‌ها از پشت‌بام‌ها آتش گشودند، از پنجره‌ها، از هر گوشه میدان؛ و مردم افتادند، صدها، هزاران، بدن‌هایشان در خیابان‌ها روی هم انباشته."),
            StoryParagraph("The massacre lasted all night; and when the sun rose, the square was silent, covered with the bodies of the dead.", "کشتار تمام شب طول کشید؛ و وقتی خورشید طلوع کرد، میدان ساکت بود، پوشیده با بدن‌های مردگان."),
            StoryParagraph("The survivors were rounded up, herded into trains, taken away to be disposed of; the bodies were loaded onto a train with two hundred cars, and the train left at midnight, bound for the sea.", "بازماندگان را جمع کردند، به قطارها راندند، برای خلاص شدن بردند؛ بدن‌ها روی قطاری با دویست واگن بار زده شدند و قطار در نیمه‌شب راه افتاد، به سمت دریا."),
            StoryParagraph("They were thrown into the ocean, one by one, the dead and the dying alike; and the sea swallowed them, and the sea was silent, and the sea did not care.", "آن‌ها را یکی‌یکی به اقیانوس انداختند، مرده و در حال مرگ یکسان؛ و دریا بلعیدشان و دریا ساکت بود و دریا اهمیتی نمی‌داد."),
            StoryParagraph("But one man survived; his name was José Arcadio Segundo, and he had been in the square, and he had seen everything.", "اما یک مرد جان به‌در برد؛ نامش خوزه آرکادیو سگوندو بود و در میدان بوده بود و همه چیز را دیده بود."),
            StoryParagraph("He had been shot, but he had not died; he had fallen among the bodies, and he had pretended to be dead, and so he had survived.", "تیر خورده بود، اما نمرده بود؛ میان بدن‌ها افتاده بود و تظاهر به مردن کرده بود و بنابراین جان سالم برده بود."),
            StoryParagraph("He returned to Macondo, and he told everyone what had happened; he told them about the massacre, about the bodies, about the train, about everything.", "به ماکوندو بازگشت و به همه گفت چه اتفاقی افتاده؛ از کشتار گفت، از بدن‌ها، از قطار، از همه چیز."),
            StoryParagraph("But no one believed him; no one wanted to believe him; they said he was crazy, they said he was drunk, they said he had made it all up.", "اما هیچ‌کس باورش نکرد؛ هیچ‌کس نمی‌خواست باورش کند؛ گفتند دیوانه است، گفتند مست است، گفتند همه‌اش را از خودش ساخته."),
            StoryParagraph("'There was no massacre,' they said. 'Nothing happened. The workers went home. Everything is fine.'", "گفتند: «کشتاری نبود. هیچ اتفاقی نیفتاد. کارگران به خانه رفتند. همه چیز خوب است.»"),
            StoryParagraph("And the newspapers agreed; and the government agreed; and the banana company agreed; and soon, everyone in Macondo agreed.", "و روزنامه‌ها موافق بودند؛ و دولت موافق بود؛ و شرکت موز موافق بود؛ و به‌زودی، همه در ماکوندو موافق شدند."),
            StoryParagraph("The massacre was erased from memory; the dead were erased from history; and Macondo continued on its way, as if nothing had happened.", "کشتار از حافظه پاک شد؛ مردگان از تاریخ پاک شدند؛ و ماکوندو به راهش ادامه داد، گویی هیچ اتفاقی نیفتاده."),
            StoryParagraph("Only José Arcadio Segundo remembered; only he knew the truth; and he spent the rest of his life trying to tell that truth to anyone who would listen.", "تنها خوزه آرکادیو سگوندو به یاد داشت؛ تنها او حقیقت را می‌دانست؛ و باقی عمرش را صرف تلاش برای گفتن آن حقیقت به هر کس که گوش می‌داد کرد."),
            StoryParagraph("But no one listened; they had all been conditioned to forget; they had all been taught to accept the official version of events.", "اما هیچ‌کس گوش نداد؛ همه شرطی شده بودند که فراموش کنند؛ همه آموخته بودند که روایت رسمی رویدادها را بپذیرند."),
            StoryParagraph("And so José Arcadio Segundo lived out his days in a small room, in the back of the house, reading and rereading the same books, trying to hold on to a memory that everyone else had abandoned.", "و اینگونه خوزه آرکادیو سگوندو روزهایش را در اتاقی کوچک، در انتهای خانه، صرف خواندن و بازخواندن همان کتاب‌ها کرد، تلاش می‌کرد خاطره‌ای را نگه دارد که همه دیگر رهایش کرده بودند."),
            StoryParagraph("He became friends with Aureliano, the young man who was studying the manuscripts, and together they would sit in the room and talk about the past.", "او با اورلیانو دوست شد، جوانی که دست‌نوشته‌ها را مطالعه می‌کرد، و با هم در اتاق می‌نشستند و از گذشته صحبت می‌کردند."),
            StoryParagraph("'You are the only one who understands,' José Arcadio Segundo would say. 'You are the only one who knows what really happened.'", "خوزه آرکادیو سگوندو می‌گفت: «تو تنها کسی هستی که می‌فهمی. تو تنها کسی هستی که می‌دانی واقعاً چه اتفاقی افتاد.»"),
            StoryParagraph("And Aureliano would nod, and he would write down what José Arcadio Segundo said, and he would add it to the manuscripts, adding another layer to the history of the family.", "و اورلیانو سر تکان می‌داد و آنچه خوزه آرکادیو سگوندو می‌گفت را می‌نوشت و به دست‌نوشته‌ها اضافه می‌کرد، لایه دیگری به تاریخ خانواده می‌افزود."),
            StoryParagraph("The years passed, and Macondo continued to decline; the banana company left, taking its jobs and its money with it, and the town fell into poverty.", "سال‌ها گذشت و ماکوندو به افول ادامه داد؛ شرکت موز رفت، شغل‌ها و پولش را با خودش برد و شهر در فقر افتاد."),
            StoryParagraph("The rain began one day, and it did not stop for four years, three months, and two days.", "باران یک روز شروع شد و چهار سال و سه ماه و دو روز متوقف نشد."),
            StoryParagraph("It rained and rained and rained; the streets turned to rivers, the houses flooded, the crops rotted in the fields.", "بارید و بارید و بارید؛ خیابان‌ها به رود تبدیل شدند، خانه‌ها سیلاب شدند، محصولات در مزارع پوسیدند."),
            StoryParagraph("The people grew weary, and then desperate, and then resigned; they forgot what the sun looked like, they forgot what dry earth felt like under their feet.", "مردم خسته شدند، بعد نومید، بعد تسلیم؛ فراموش کردند خورشید چه شکلی است، فراموش کردند خاک خشک زیر پایشان چه حسی دارد."),
            StoryParagraph("And when the rain finally stopped, when the sun finally returned, Macondo was not the same; it was a ghost of what it had been, a ruin of a town, a memory of a place that had once been alive.", "و وقتی باران سرانجام ایستاد، وقتی خورشید سرانجام بازگشت، ماکوندو همان نبود؛ شبحی بود از آنچه بوده، ویرانه‌ای از یک شهر، خاطره‌ای از جایی که زمانی زنده بوده."),
            StoryParagraph("The Buendía family was dying out; one by one, the members had died or left or gone mad; and soon, there would be no one left.", "خانواده بوئندیا در حال منقرض شدن بود؛ یکی‌یکی، اعضا مرده بودند یا رفته بودند یا دیوانه شده بودند؛ و به‌زودی کسی باقی نمی‌ماند."),
            StoryParagraph("And so the story moved toward its inevitable end, the end that had been written in the manuscripts of Melquíades, the end that no one could prevent.", "و اینگونه داستان به سمت پایان اجتناب‌ناپذیرش پیش رفت، پایانی که در دست‌نوشته‌های مِلکیادس نوشته شده بود، پایانی که هیچ‌کس نمی‌توانست مانعش شود."),
            StoryParagraph("For Macondo, like all things, had its beginning, its middle, and its end; and the end was approaching, slowly, surely, unstoppably.", "زیرا ماکوندو، همچون همه چیز، آغاز و میانه و پایانی داشت؛ و پایان نزدیک می‌شد، آهسته، به‌طور قطعی، غیرقابل توقف.")
        )
    )

    // ─────────── فصل ۵: تنهایی خانواده ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The Solitude of the Family", titlePersian = "تنهایی خانواده",
        paragraphs = listOf(
            StoryParagraph("The Buendía family had always been solitary, but now, in its final years, that solitude became total, absolute, inescapable.", "خانواده بوئندیا همیشه تنها بودند، اما حالا، در سال‌های آخرش، آن تنهایی کل، مطلق، گریزناپذیر شد."),
            StoryParagraph("Amaranta, the daughter, had grown old alone; she had never married, never loved, never left the house.", "آمارانتا، دختر، تنها پیر شده بود؛ هرگز ازدواج نکرده، هرگز عشق نورزیده، هرگز از خانه بیرون نرفته بود."),
            StoryParagraph("She spent her days weaving a shroud for herself, a shroud she would never finish, because she knew that when she finished it, she would die.", "روزهایش را صرف بافتن کفنی برای خودش می‌کرد، کفنی که هرگز تمام نمی‌کرد، چون می‌دانست وقتی تمامش کند، می‌میرد."),
            StoryParagraph("And so she wove, and she unwove, and she wove again; and the days turned into weeks, and the weeks into months, and the months into years.", "و اینگونه بافت و باز کرد و دوباره بافت؛ و روزها به هفته‌ها تبدیل شدند و هفته‌ها به ماه‌ها و ماه‌ها به سال‌ها."),
            StoryParagraph("She had loved and lost, in her youth; and the loss had hardened her, had closed her off, had made her incapable of love.", "او در جوانی عشق ورزیده و از دست داده بود؛ و فقدان سختش کرده بود، بسته بودش، ناتوانش کرده بود از عشق."),
            StoryParagraph("She had driven away every suitor, every friend, every person who tried to get close to her; she had chosen solitude, and solitude had chosen her.", "هر خواستگاری را رانده بود، هر دوستی، هر کسی که تلاش کرده بود نزدیک شود؛ تنهایی را برگزیده بود و تنهایی او را برگزیده بود."),
            StoryParagraph("Rebeca, her adopted sister, had also grown old; but she had grown old differently, in a small house at the edge of town, with a servant who was her only companion.", "ربکا، خواهر خوانده‌اش، او هم پیر شده بود؛ اما متفاوت پیر شده بود، در خانه‌ای کوچک در حاشیه شهر، با خدمتکاری که تنها همدمش بود."),
            StoryParagraph("She had married, once, but her husband had died young, and she had never remarried; she had lived the rest of her life alone, waiting for a death that took its time in coming.", "او یک بار ازدواج کرده بود، اما شوهرش جوان مرده بود و هرگز دوباره ازدواج نکرده بود؛ باقی عمرش را تنها زندگی کرده بود، منتظر مرگی که در آمدنش وقت می‌گذاشت."),
            StoryParagraph("Úrsula, the matriarch, was now over a hundred years old; she had become small and shriveled, and she had lost her sight, and she had lost her memory.", "اورسولا، بزرگ‌مادر، حالا بیش از صد سال داشت؛ کوچک و چروکیده شده بود و بینایی‌اش را از دست داده بود و حافظه‌اش را از دست داده بود."),
            StoryParagraph("She sat in her rocking chair, day after day, staring at nothing, humming songs from her childhood, waiting for a death that she had long since ceased to fear.", "روز پس از روز در صندلی گهواره‌ای‌اش می‌نشست، به هیچ نگاه می‌کرد، آهنگ‌های کودکی‌اش را زیر لب می‌خواند، منتظر مرگی که مدت‌ها بود از آن نمی‌ترسید."),
            StoryParagraph("She had seen her family rise, and she had seen it fall; she had seen her sons go to war and never return; she had seen her daughters grow old and die alone.", "او دیده بود خانواده‌اش برمی‌خیزد و دیده بود فرو می‌ریزد؛ دیده بود پسرانش به جنگ می‌روند و هرگز بازنمی‌گردند؛ دیده بود دخترانش پیر می‌شوند و تنها می‌میرند."),
            StoryParagraph("She had seen her great-grandchildren born, and she had seen them die; she had seen the family tree branch out and wither, all in the span of her long, long life.", "دیده بود نتیجه‌هایش به دنیا می‌آیند و دیده بود می‌میرند؛ دیده بود شجره‌نامه خانواده شاخه می‌دواند و پژمرده می‌شود، همه در طول عمر طولانی و طولانی‌اش."),
            StoryParagraph("And still she lived; and still she waited; and still she hummed her songs; and she did not know why she continued to exist.", "و هنوز زنده بود؛ و هنوز منتظر بود؛ و هنوز آهنگ‌هایش را زیر لب می‌خواند؛ و نمی‌دانست چرا به وجودش ادامه می‌دهد."),
            StoryParagraph("Meanwhile, in the room at the back of the house, Aureliano and José Arcadio Segundo were studying the manuscripts together.", "در همین حال، در اتاق انتهای خانه، اورلیانو و خوزه آرکادیو سگوندو با هم دست‌نوشته‌ها را مطالعه می‌کردند."),
            StoryParagraph("They had become friends, these two solitary men, the last of their generation; they shared their solitude, and in sharing it, they found something like companionship.", "این دو مرد تنها، آخرین نفرات نسلشان، با هم دوست شده بودند؛ تنهایی‌شان را قسمت می‌کردند و در قسمت کردنش، چیزی شبیه به همراهی می‌یافتند."),
            StoryParagraph("Aureliano had learned to read Sanskrit, and he was beginning to understand the manuscripts; he was beginning to see the patterns, the cycles, the repetitions.", "اورلیانو سانسکریت خواندن آموخته بود و شروع کرده بود به فهمیدن دست‌نوشته‌ها؛ شروع کرده بود به دیدن الگوها، چرخه‌ها، تکرارها."),
            StoryParagraph("He saw that the family history was not a line but a circle; the same events, the same names, the same fates, repeating themselves over and over.", "می‌دید تاریخ خانواده یک خط نبود بلکه دایره‌ای بود؛ همان رویدادها، همان نام‌ها، همان سرنوشت‌ها، خودشان را بارها و بارها تکرار می‌کردند."),
            StoryParagraph("He saw that his great-grandfather had been like his grandfather, and his grandfather like his father, and his father like himself; they were all the same man, living the same life, repeating the same mistakes.", "می‌دید پدرجدش مثل پدربزرگش بوده و پدربزرگش مثل پدرش و پدرش مثل خودش؛ همه‌شان همان یک مرد بودند، همان زندگی را می‌کردند، همان اشتباهات را تکرار می‌کردند."),
            StoryParagraph("And he saw that he himself was not free; that his fate, too, had been written; that he, like all the others, was a prisoner of the past.", "و می‌دید خودش هم آزاد نیست؛ سرنوشتش هم نوشته شده بود؛ او هم مثل همه دیگران زندانی گذشته بود."),
            StoryParagraph("This realization filled him with despair, but it also filled him with a strange kind of peace; for if his fate was already written, then he did not need to fight it.", "این درک او را پر از ناامیدی کرد، اما نوعی آرامش عجیب هم پر کرد؛ زیرا اگر سرنوشتش از قبل نوشته شده بود، پس نیازی نبود با آن بجنگد."),
            StoryParagraph("He could simply accept; he could simply be; he could simply live out the days that remained to him, without hope, without fear, without expectation.", "می‌توانست تنها بپذیرد؛ می‌توانست تنها باشد؛ می‌توانست تنها روزهای باقی‌مانده را بگذراند، بدون امید، بدون ترس، بدون انتظار."),
            StoryParagraph("And so he did; and so he waited; and so the days passed; and so the family continued its slow, inevitable decline.", "و اینگونه کرد؛ و اینگونه منتظر ماند؛ و اینگونه روزها گذشتند؛ و اینگونه خانواده به افول آرام و اجتناب‌ناپذیرش ادامه داد."),
            StoryParagraph("One by one, the last members of the family died; one by one, the rooms of the house were emptied; one by one, the memories faded into silence.", "یکی‌یکی، آخرین اعضای خانواده مردند؛ یکی‌یکی، اتاق‌های خانه خالی شدند؛ یکی‌یکی، خاطرات در سکوت محو شدند."),
            StoryParagraph("Amaranta finished her shroud, and died, as she had known she would.", "آمارانتا کفنش را تمام کرد و مرد، همانطور که می‌دانست."),
            StoryParagraph("Rebeca was found dead in her house, alone, forgotten, unmourned.", "ربکا در خانه‌اش مرده پیدا شد، تنها، فراموش‌شده، بی‌عزادار."),
            StoryParagraph("Úrsula, the matriarch, died at last, in her rocking chair, at the age of one hundred and fifteen or twenty; no one knew exactly, for she had lost count of her years.", "اورسولا، بزرگ‌مادر، سرانجام در صندلی گهواره‌ای‌اش مرد، در سن صد و پانزده یا بیست سالگی؛ هیچ‌کس دقیق نمی‌دانست، زیرا شمارش سال‌هایش را از دست داده بود."),
            StoryParagraph("Aureliano Segundo died, and his twin brother José Arcadio Segundo died on the same day, and they were buried in the same grave, as they had been born in the same bed.", "اورلیانو سگوندو مرد و برادر دوقلویش خوزه آرکادیو سگوندو همان روز مرد و در همان گور دفن شدند، همانطور که در همان بستر زاده شده بودند."),
            StoryParagraph("The house grew silent; the house grew dark; the house grew old; and the last of the Buendía line was born, and his name was Aureliano, and he was the son of Meme and a man whose name no one knew.", "خانه ساکت شد؛ خانه تاریک شد؛ خانه پیر شد؛ و آخرین نفر از نسل بوئندیا به دنیا آمد و نامش اورلیانو بود و پسر ممه و مردی بود که نامش را هیچ‌کس نمی‌دانست."),
            StoryParagraph("And this Aureliano, the last of his line, would grow up in the house that was falling apart, with the aunt who was dying, and the great-great-grandmother who was already dead.", "و این اورلیانو، آخرین نفر از نسلش، در خانه‌ای بزرگ می‌شد که در حال از هم پاشیدن بود، با خاله‌ای که در حال مردن بود و مادربزرگ‌مادربزرگی که از قبل مرده بود."),
            StoryParagraph("And he would discover the manuscripts, and he would learn to read them, and he would learn the truth about his family, the truth that no one else had ever known.", "و او دست‌نوشته‌ها را کشف می‌کرد و یاد می‌گرفت بخواندشان و حقیقت درباره خانواده‌اش را می‌آموخت، حقیقتی که هیچ‌کس دیگری هرگز ندانسته بود."),
            StoryParagraph("And when he learned it, when he understood what had happened, and what was happening, and what was about to happen, he would also learn that he could not change it, that he could not escape it, that his fate, like the fate of all the Buendías, was already written.", "و وقتی آموخت، وقتی فهمید چه اتفاقی افتاده و چه اتفاقی می‌افتد و چه اتفاقی در شرف وقوع است، می‌آموخت که نمی‌تواند تغییرش دهد، نمی‌تواند از آن بگریزد، سرنوشتش مثل سرنوشت همه بوئندیاها، از قبل نوشته شده بود."),
            StoryParagraph("And so the solitude of the family became total; and so the solitude of Macondo became absolute; and so the story moved toward its final pages, the pages that Melquíades had written a hundred years before.", "و اینگونه تنهایی خانواده کل شد؛ و اینگونه تنهایی ماکوندو مطلق شد؛ و اینگونه داستان به سمت صفحه‌های آخرش پیش رفت، صفحه‌هایی که مِلکیادس صد سال پیش نوشته بود.")
        )
    )

    // ─────────── فصل ۶: پایان ماکوندو ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The End of Macondo", titlePersian = "پایان ماکوندو",
        paragraphs = listOf(
            StoryParagraph("Aureliano Babilonia, the last of the Buendía line, had spent his entire life in the house; he had never left Macondo, never seen the sea, never known the world beyond the swamps.", "اورلیانو بابلونیا، آخرین نفر از نسل بوئندیا، تمام عمرش را در خانه گذرانده بود؛ هرگز ماکوندو را ترک نکرده بود، هرگز دریا را ندیده بود، هرگز جهانی فراتر از باتلاق‌ها را نمی‌شناخت."),
            StoryParagraph("He had been raised by his aunt Amaranta Úrsula, the last surviving member of the family; she had loved him, protected him, taught him everything she knew.", "او توسط خاله‌اش آمارانتا اورسولا، آخرین عضو بازمانده خانواده، بزرگ شده بود؛ او دوستش داشت، محافظتش می‌کرد، هر چه می‌دانست به او می‌آموخت."),
            StoryParagraph("But Amaranta Úrsula was not his aunt; she was his cousin, or perhaps something more complicated; the family tree had become so tangled that no one could untangle it.", "اما آمارانتا اورسولا خاله‌اش نبود؛ دخترعمویش بود، یا شاید چیز پیچیده‌تری؛ شجره‌نامه خانواده چنان درهم پیچیده شده بود که هیچ‌کس نمی‌توانست بازش کند."),
            StoryParagraph("They had fallen in love, these two, without knowing the truth about their relationship; and their love had been passionate, and their love had been doomed.", "این دو، بدون دانستن حقیقت درباره نسبتشان، عاشق شده بودند؛ و عشقشان پرشور بود و عشقشان محکوم به فنا بود."),
            StoryParagraph("Amaranta Úrsula became pregnant, and she gave birth to a son, a boy with a pig's tail, the child that had been prophesied for generations.", "آمارانتا اورسولا باردار شد و پسری به دنیا آورد، پسری با دمی خوک، همان بچه‌ای که نسل‌ها پیش‌بینی شده بود."),
            StoryParagraph("She died in childbirth, bleeding to death on the bed where she had been born; and Aureliano was left alone with the child, the last of the Buendías.", "او در زایمان مرد، روی تختی که در آن زاده شده بود از خونریزی مرد؛ و اورلیانو با بچه تنها ماند، آخرین نفر از بوئندیاها."),
            StoryParagraph("He had no one to help him; the house was empty; the town was empty; the world was empty; and he was alone with his grief and his child and the manuscripts.", "کسی را نداشت که کمکش کند؛ خانه خالی بود؛ شهر خالی بود؛ جهان خالی بود؛ و او با اندوهش و بچه‌اش و دست‌نوشته‌ها تنها بود."),
            StoryParagraph("He remembered that Melquíades had said the manuscripts contained the history of the family, and he resolved to read them, to understand them, to learn the truth.", "به یاد آورد مِلکیادس گفته بود دست‌نوشته‌ها تاریخ خانواده را در خود دارند و تصمیم گرفت بخواندشان، بفهمدشان، حقیقت را بیاموزد."),
            StoryParagraph("He had learned Sanskrit years before, from Melquíades himself, though Melquíades had been dead for decades; but the room where the manuscripts were kept was still there, and the ghost of Melquíades still lingered.", "سال‌ها پیش سانسکریت آموخته بود، از خود مِلکیادس، هرچند مِلکیادس دهه‌ها بود مرده بود؛ اما اتاقی که دست‌نوشته‌ها در آن بودند هنوز بود و شبح مِلکیادس هنوز پرسه می‌زد."),
            StoryParagraph("He went to the room, and he took out the manuscripts, and he began to read; and as he read, the story of his family unfolded before his eyes.", "به اتاق رفت و دست‌نوشته‌ها را بیرون آورد و شروع به خواندن کرد؛ و همانطور که می‌خواند، داستان خانواده‌اش پیش چشمانش گشوده شد."),
            StoryParagraph("He read about José Arcadio Buendía, the founder of Macondo, who had killed a man and been haunted by his ghost.", "درباره خوزه آرکادیو بوئندیا خواند، بنیان‌گذار ماکوندو، که مردی را کشته بود و شبحش تسخیرش می‌کرد."),
            StoryParagraph("He read about Úrsula, the matriarch, who had lived for more than a century and had seen her family rise and fall.", "درباره اورسولا خواند، بزرگ‌مادر، که بیش از یک قرن زندگی کرده بود و دیده بود خانواده‌اش برمی‌خیزد و فرو می‌ریزد."),
            StoryParagraph("He read about Colonel Aureliano Buendía, who had fought thirty-two wars and had made little gold fishes until the day he died.", "درباره سرهنگ اورلیانو بوئندیا خواند، که سی و دو جنگ جنگیده بود و تا روز مرگش ماهی‌های طلایی کوچک ساخته بود."),
            StoryParagraph("He read about Amaranta, who had woven a shroud and had died the day she finished it.", "درباره آمارانتا خواند، که کفنی بافته بود و روزی که تمامش کرد مرده بود."),
            StoryParagraph("He read about Rebeca, who had eaten earth and had died alone; about Pietro Crespi, who had killed himself for love; about Remedios the Beauty, who had ascended to heaven.", "درباره ربکا خواند، که خاک خورده بود و تنها مرده بود؛ درباره پیترو کرسپی، که از عشق خودکشی کرده بود؛ درباره رمدیوس زیبا، که به آسمان عروج کرده بود."),
            StoryParagraph("He read about the seventeen Aurelianos, all killed in a single night; about the banana massacre, which everyone had forgotten; about the four years of rain, which had destroyed the town.", "درباره هفده اورلیانو خواند، همه در یک شب کشته شده؛ درباره کشتار موز، که همه فراموش کرده بودند؛ درباره چهار سال باران، که شهر را نابود کرده بود."),
            StoryParagraph("He read about his own mother, Meme, and her forbidden love; about his grandmother, Fernanda, and her rigid piety; about his great-grandmother, Santa Sofía de la Piedad, and her silent endurance.", "درباره مادر خودش، ممه، و عشق ممنوعه‌اش خواند؛ درباره مادربزرگش، فرناندا، و تقوایش سخت؛ درباره مادربزرگ‌مادربزرگش، سانتا سوفیا د لا پیداد، و تحمل ساکتش."),
            StoryParagraph("And then he read about himself, and about Amaranta Úrsula, and about their love, and about their child; and he understood, at last, the truth about his family.", "و سپس درباره خودش خواند و درباره آمارانتا اورسولا و درباره عشقشان و درباره بچه‌شان؛ و سرانجام حقیقت درباره خانواده‌اش را فهمید."),
            StoryParagraph("He understood that the family had been cursed from the beginning, cursed with solitude, cursed with repetition, cursed with the inability to escape their fate.", "فهمید خانواده از آغاز نفرین شده بود، به تنهایی نفرین شده، به تکرار نفرین شده، به ناتوانی از گریز از سرنوشتشان نفرین شده."),
            StoryParagraph("He understood that everything that had happened had been foretold, that every death, every birth, every love, every loss, had been written in the manuscripts a hundred years before.", "فهمید هر چه اتفاق افتاده بود پیش‌بینی شده بود، هر مرگ، هر تولد، هر عشق، هر فقدان، صد سال پیش در دست‌نوشته‌ها نوشته شده بود."),
            StoryParagraph("And he understood that he was not reading a record of the past, but a prophecy of the future, a future that was unfolding in the very moment that he read it.", "و فهمید او در حال خواندن سابقه گذشته نبود، بلکه پیشگویی آینده بود، آینده‌ای که در همان لحظه‌ای که می‌خواند در حال باز شدن بود."),
            StoryParagraph("For the manuscripts were not merely a history; they were the present, and they were the future, and they were the end.", "زیرا دست‌نوشته‌ها تنها تاریخ نبودند؛ حال بودند و آینده بودند و پایان بودند."),
            StoryParagraph("He came to the final page, and he read the final prophecy: that the last of the Buendía line would be eaten by ants, and that the town of Macondo would be destroyed by a hurricane, and that nothing would remain of either.", "به آخرین صفحه رسید و آخرین پیشگویی را خواند: آخرین نفر از نسل بوئندیا توسط مورچه‌ها خورده می‌شود و شهر ماکوندو توسط طوفانی نابود می‌شود و از هیچ‌کدام چیزی باقی نمی‌ماند."),
            StoryParagraph("He heard a noise behind him, and he turned, and he saw that his son, the child with the pig's tail, was being carried away by ants.", "صدایی از پشت سرش شنید و برگشت و دید پسرش، بچه با دم خوک، توسط مورچه‌ها برده می‌شود."),
            StoryParagraph("He ran to save him, but it was too late; the ants had already disappeared into their tunnels, taking the child with them.", "برای نجاتش دوید، اما دیر شده بود؛ مورچه‌ها از قبل در تونل‌هایشان ناپدید شده بودند، بچه را با خودشان برده بودند."),
            StoryParagraph("And then he understood that the manuscripts were true, that everything had been foretold, that he had been living his life not freely but according to a script that had been written long before his birth.", "و بعد فهمید دست‌نوشته‌ها واقعی هستند، همه چیز پیش‌بینی شده بود، او زندگی‌اش را نه آزادانه بلکه طبق متنی که خیلی پیش از تولدش نوشته شده بود زیسته بود."),
            StoryParagraph("He turned to the manuscripts one last time, to read the final words, to see what would become of him.", "یک بار آخر به دست‌نوشته‌ها برگشت تا کلمات آخر را بخواند، ببیند بر سر خودش چه می‌آید."),
            StoryParagraph("And the words said: 'The first of the line is tied to a tree and the last is being eaten by the ants.'", "و کلمات می‌گفتند: «نخستین نفر از نسل به درختی بسته است و آخرین نفر توسط مورچه‌ها خورده می‌شود.»"),
            StoryParagraph("And then the wind began to blow, a wind that came from nowhere and went everywhere, a wind that was the hurricane that Melquíades had foretold.", "و بعد باد شروع به وزیدن کرد، بادی که از هیچ‌جا می‌آمد و به همه‌جا می‌رفت، بادی که همان طوفانی بود که مِلکیادس پیشگویی کرده بود."),
            StoryParagraph("The house began to shake, the walls began to crack, the roof began to collapse; and Aureliano knew that he could not escape, that he did not want to escape, that his fate was the fate of Macondo.", "خانه شروع به لرزیدن کرد، دیوارها ترک خوردند، سقف فرو ریخت؛ و اورلیانو می‌دانست نمی‌تواند بگریزد، نمی‌خواهد بگریزد، سرنوشتش همان سرنوشت ماکوندو بود."),
            StoryParagraph("For it was written that Macondo would be destroyed by a hurricane, and that it would be erased from the memory of men, and that no one would ever remember that it had existed.", "زیرا نوشته شده بود ماکوندو توسط طوفانی نابود می‌شود و از حافظه انسان‌ها پاک می‌شود و هیچ‌کس هرگز به یاد نمی‌آورد که وجود داشته."),
            StoryParagraph("He picked up the manuscripts and held them to his chest, and he kept reading, even as the wind tore at him, even as the house fell around him, even as the world came to an end.", "دست‌نوشته‌ها را برداشت و به سینه‌اش چسباند و به خواندن ادامه داد، حتی همانطور که باد او را می‌درید، حتی همانطور که خانه دورش فرو می‌ریخت، حتی همانطور که جهان به پایان می‌رسید."),
            StoryParagraph("For in those final moments, in the act of reading, in the act of understanding, he had found what he had been seeking his whole life: the truth.", "زیرا در آن لحظه‌های آخر، در عمل خواندن، در عمل فهمیدن، آنچه تمام عمرش در جستجویش بود را یافته بود: حقیقت."),
            StoryParagraph("The truth that he was not free, and that no one is free; the truth that our lives are written before we live them; the truth that the end is the beginning and the beginning is the end.", "حقیقت اینکه او آزاد نیست و هیچ‌کس آزاد نیست؛ حقیقت اینکه زندگی‌هایمان پیش از زیستنمان نوشته شده‌اند؛ حقیقت اینکه پایان آغاز است و آغاز پایان."),
            StoryParagraph("And as the wind lifted him up, as the house dissolved into dust, as Macondo disappeared from the earth, he laughed, and he wept, and he knew that he was, at last, free.", "و همانطور که باد او را بلند می‌کرد، همانطور که خانه به غبار حل می‌شد، همانطور که ماکوندو از زمین ناپدید می‌شد، خندید و گریست و دانست که سرانجام آزاد است."),
            StoryParagraph("For only the dead are truly free; only those who have lived out their fate are free of fate; only those who have reached the end are free of the journey.", "زیرا تنها مردگان به‌راستی آزادند؛ تنها کسانی که سرنوشتشان را زیسته‌اند از سرنوشت آزادند؛ تنها کسانی که به پایان رسیده‌اند از سفر آزادند."),
            StoryParagraph("And so Macondo was destroyed, and so the Buendía family came to an end, and so one hundred years of solitude were completed, and so the story that had been told for generations was finally finished.", "و اینگونه ماکوندو نابود شد و اینگونه خانواده بوئندیا به پایان رسید و اینگونه صد سال تنهایی کامل شد و اینگونه داستانی که نسل‌ها تعریف شده بود سرانجام تمام شد."),
            StoryParagraph("But the story does not end here; for the story of the Buendías is the story of every family, of every town, of every human being who has ever lived and loved and died.", "اما داستان اینجا تمام نمی‌شود؛ زیرا داستان بوئندیاها داستان هر خانواده است، هر شهر، هر انسانی که هرگز زیسته و عشق ورزیده و مرده."),
            StoryParagraph("And so the story continues; and so the cycle repeats; and so, somewhere, in some other Macondo, in some other family, the same events are unfolding, the same fates are being fulfilled, the same solitude is being suffered.", "و اینگونه داستان ادامه می‌یابد؛ و اینگونه چرخه تکرار می‌شود؛ و اینگونه، جایی، در ماکوندوی دیگری، در خانواده دیگری، همان رویدادها در حال باز شدن هستند، همان سرنوشت‌ها در حال تحقق یافتن، همان تنهایی در حال تحمل شدن."),
            StoryParagraph("For there is no final ending, only endless endings; and there is no final story, only endless stories; and there is no final solitude, only the solitude that each of us must bear, alone, in our own way.", "زیرا هیچ پایان نهایی نیست، تنها پایان‌های بی‌پایان؛ و هیچ داستان نهایی نیست، تنها داستان‌های بی‌پایان؛ و هیچ تنهایی نهایی نیست، تنها تنهایی‌ای که هر یک از ما باید تحملش کنیم، تنها، به شیوه خودمان."),
            StoryParagraph("And so the story of Macondo ends, but it also begins; for every end is a beginning, and every beginning is an end, in the endless cycle that is the story of humanity.", "و اینگونه داستان ماکوندو تمام می‌شود، اما همچنین آغاز می‌شود؛ زیرا هر پایانی آغازی است و هر آغازی پایانی، در چرخه بی‌پایانی که داستان بشریت است."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز.")
        )
    )
}